Q: Dynamically Adding Row With Dropdown Ajax Calls in Codeigniter A: <h2>Controller (CodeIgniter)</h2>
<p><strong>application/controllers/Products.php</strong></p>
<p>class Products extends CI_Controller {</p>
<pre><code>public function __construct()
{
    parent::__construct();
    $this-&gt;load-&gt;model('Product_model');
}

// AJAX: return dropdown options
public function get_categories()
{
    $categories = $this-&gt;Product_model-&gt;get_categories();
    echo json_encode($categories);
}
</code></pre>
<p>}</p>
