function loadCategories() {
    $.ajax({
        url: "",
        type: "GET",
        dataType: "json",
        success: function (data) {
            let options = 'Select';
            $.each(data, function (i, item) {
                options += `${item.name}`;
            });

            $('.category').html(options);
